mapper.sql:
EXISTS (
    SELECT 1
    FROM ifj_instance job_instance
    WHERE job_instance.id = #{decision.jobInstanceId}
      AND job_instance.root_instance_id = #{rootInstanceId}
      AND job_instance.trigger_id = #{triggerId}
      AND job_instance.execution_fence = #{decision.executionFence}
      AND (
          #{decision.executionFence} = 0
          OR EXISTS (
              SELECT 1
              FROM ifj_trigger_work_item work_item
              WHERE work_item.trigger_id = #{triggerId}
                AND work_item.root_instance_id = #{rootInstanceId}
                AND work_item.status = 'CLAIMED'
                AND work_item.fence_token = #{decision.executionFence}
                AND work_item.lease_deadline > CURRENT_TIMESTAMP(3)
          )
      )
)

mapper.insert:
INSERT INTO ifj_dag_gateway_decision (
    id, job_instance_id, definition_node_id, evaluation_no,
    selected_edge_ids, context_digest, evaluator_version, status,
    error_code, execution_fence, create_time
)
SELECT
    #{decision.id}, #{decision.jobInstanceId}, #{decision.definitionNodeId},
    #{decision.evaluationNo}, #{decision.selectedEdgeIds},
    #{decision.contextDigest}, #{decision.evaluatorVersion},
    #{decision.status}, #{decision.errorCode}, #{decision.executionFence},
    #{decision.createTime}
WHERE EXISTS (
    SELECT 1 FROM ifj_instance job_instance
    WHERE job_instance.id = #{decision.jobInstanceId}
      AND job_instance.root_instance_id = #{rootInstanceId}
      AND job_instance.trigger_id = #{triggerId}
      AND job_instance.execution_fence = #{decision.executionFence}
      AND (#{decision.executionFence} = 0 OR EXISTS (
          SELECT 1 FROM ifj_trigger_work_item work_item
          WHERE work_item.trigger_id = #{triggerId}
            AND work_item.root_instance_id = #{rootInstanceId}
            AND work_item.status = 'CLAIMED'
            AND work_item.fence_token = #{decision.executionFence}
            AND work_item.lease_deadline > strftime('%Y-%m-%d %H:%M:%f','now')
      ))
)

INSERT INTO ifj_dag_gateway_decision (
    id, job_instance_id, definition_node_id, evaluation_no,
    selected_edge_ids, context_digest, evaluator_version, status,
    error_code, execution_fence, create_time
)
SELECT
    #{decision.id}, #{decision.jobInstanceId}, #{decision.definitionNodeId},
    #{decision.evaluationNo}, #{decision.selectedEdgeIds},
    #{decision.contextDigest}, #{decision.evaluatorVersion},
    #{decision.status}, #{decision.errorCode}, #{decision.executionFence},
    #{decision.createTime}
FROM dual
WHERE EXISTS (
    SELECT 1 FROM ifj_instance job_instance
    WHERE job_instance.id = #{decision.jobInstanceId}
      AND job_instance.root_instance_id = #{rootInstanceId}
      AND job_instance.trigger_id = #{triggerId}
      AND job_instance.execution_fence = #{decision.executionFence}
      AND (#{decision.executionFence} = 0 OR EXISTS (
          SELECT 1 FROM ifj_trigger_work_item work_item
          WHERE work_item.trigger_id = #{triggerId}
            AND work_item.root_instance_id = #{rootInstanceId}
            AND work_item.status = 'CLAIMED'
            AND work_item.fence_token = #{decision.executionFence}
            AND work_item.lease_deadline > CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3))
      ))
)

